files.src/model.rs:
pub struct Segment {
     pub name: String,
     pub seal_id: Option<String>,
     pub bytes: u64,
 }

files.src/errors.rs:
#[derive(Debug)]
 pub enum PublishError { MissingSeal, EmptySegment }
 impl PublishError {
     pub fn code(&self) -> &'static str {
         match self {
             Self::MissingSeal => "SEGMENT_SEAL_REQUIRED",
             Self::EmptySegment => "SEGMENT_EMPTY",
         }
     }
 }

files.src/seal.rs:
use crate::{errors::PublishError, model::Segment};
 pub fn require_segment_seal(segment: &Segment) -> Result<(), PublishError> {
     if segment.seal_id.as_deref().unwrap_or("").is_empty() {
         return Err(PublishError::MissingSeal);
     }
     Ok(())
 }

files.src/journal.rs:
use crate::{errors::PublishError, model::Segment};
 pub fn append_segment(segment: &Segment) -> Result<String, PublishError> {
     if segment.bytes == 0 { return Err(PublishError::EmptySegment); }
     Ok(format!("journal:{}", segment.name))
 }

files.src/service.rs:
use crate::{model::Segment, seal::require_segment_seal, journal::append_segment};
 pub fn publish(segment: &Segment) -> Result<String, &'static str> {
     require_segment_seal(segment).map_err(|e| e.code())?;
     append_segment(segment).map_err(|e| e.code())
 }
